// Общие шаги для тестов доступа к служебным разделам (план specs/admin-access.md). Только чтение.
// Хлебные крошки на пути редиректа (#26087e6e) — отдельные тесты на crumb-helpers.ts.
import { expect, Locator, Page } from '@playwright/test';

export const DASHBOARD_URL = /\/dashboard(\?|#|$)/;

/** Вкладка служебного раздела: tab или button, имя начинается с текста (у Support Console рядом счётчик). */
export function sectionTab(page: Page, name: string): Locator {
  const re = new RegExp('^' + name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '(\\s*\\d+)?$');
  return page.getByRole('tab', { name: re }).or(page.getByRole('button', { name: re }));
}

/** Боковое меню загружено. */
export async function waitForMenu(page: Page) {
  await expect(page.getByRole('link', { name: 'Jobs', exact: true })).toBeVisible();
}

/** Пользователь на /dashboard, без экрана отказа и без вкладок Support Console. */
export async function expectNoSupportConsole(page: Page) {
  await expect(page.getByText('Access Denied')).toHaveCount(0);
  await expect(page.getByText('Only support staff can access the support console.')).toHaveCount(0);
  // «Chat» не проверяем: слишком общее имя (у пользователя может быть своя кнопка чата) — хватает двух специфичных вкладок.
  for (const t of ['Bug Report', 'Support Task']) await expect(sectionTab(page, t)).toHaveCount(0);
}

/** Пользователь без экрана отказа и без вкладок Admin Panel. */
export async function expectNoAdminPanel(page: Page) {
  await expect(page.getByText('Access Denied')).toHaveCount(0);
  for (const t of ['Users', 'Plans', 'Funnel']) await expect(sectionTab(page, t)).toHaveCount(0);
  await expect(page.getByRole('button', { name: 'Assign plan', exact: true })).toHaveCount(0);
}
